import json,pathlib,subprocess
r={}
for name in ['gro_flush_timeout','napi_defer_hard_irqs']:
 p=pathlib.Path('/sys/class/net/enp97s0')/name
 try:r[str(p)]={'value':p.read_text().strip()}
 except OSError as e:r[str(p)]={'error':str(e)}
for name in ['busy_poll','busy_read']:
 p=pathlib.Path('/proc/sys/net/core')/name
 try:r[str(p)]={'value':p.read_text().strip()}
 except OSError as e:r[str(p)]={'error':str(e)}
device=pathlib.Path('/sys/class/net/enp97s0/device');r['device_realpath']=str(device.resolve());r['driver_realpath']=str((device/'driver').resolve())
for name in ['vendor','device','subsystem_vendor','subsystem_device','class','irq','numa_node','current_link_speed','current_link_width','max_link_speed','max_link_width','local_cpulist']:
 p=device/name
 try:r[str(p)]={'value':p.read_text().strip()}
 except OSError as e:r[str(p)]={'error':str(e)}
p=device/'msi_irqs'
try:r['msi_irqs']={x.name:x.read_text().strip() for x in p.iterdir()}
except OSError as e:r['msi_irqs']={'error':str(e)}
p=subprocess.run(['lspci','-nnk','-s','61:00.0'],text=True,capture_output=True);r['lspci_nnk']={'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
p=subprocess.run(['lspci','-vv','-s','61:00.0'],text=True,capture_output=True);r['lspci_vv']={'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
print(json.dumps(r,indent=2))
